import java.util.List;

public class WordFilterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        ArrayList<String> a = new ArrayList<>(List.of("to", "tree", "a", "lamp"));
        ArrayList<String> resultA = WordFilter.removeShorterThan(a, 3);
        check("removeShorterThan([to, tree, a, lamp], 3)", "[tree, lamp]",
                resultA == null ? null : resultA.toString());
        check("returns the same list object", true, resultA == a);

        ArrayList<String> b = new ArrayList<>(List.of("a", "b", "c", "dddd"));
        ArrayList<String> resultB = WordFilter.removeShorterThan(b, 2);
        check("adjacent short words are all removed", "[dddd]",
                resultB == null ? null : resultB.toString());

        ArrayList<String> c = new ArrayList<>(List.of("apple", "berry"));
        ArrayList<String> resultC = WordFilter.removeShorterThan(c, 3);
        check("nothing shorter than minLen", "[apple, berry]",
                resultC == null ? null : resultC.toString());

        ArrayList<String> d = new ArrayList<>(List.of("x", "yy", "zzz"));
        ArrayList<String> resultD = WordFilter.removeShorterThan(d, 5);
        check("everything removed", "[]",
                resultD == null ? null : resultD.toString());

        ArrayList<String> e = new ArrayList<>();
        ArrayList<String> resultE = WordFilter.removeShorterThan(e, 4);
        check("empty list stays empty", "[]",
                resultE == null ? null : resultE.toString());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
